--
-- Table structure for table `cromos`
--

DROP TABLE IF EXISTS `cromos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `cromos` (
  `id_cromo` int(11) NOT NULL AUTO_INCREMENT,
  `nombre` varchar(100) NOT NULL,
  `posicion` enum('POR','DF','MC','DC','ENT','GER','ESCUDO','PRESIDENTE') NOT NULL,
  `descripcion` text DEFAULT NULL,
  `imagen` varchar(255) DEFAULT NULL,
  `id_expansion` int(11) NOT NULL,
  `id_equipo` int(11) NOT NULL,
  `universo` enum('srf','ie') NOT NULL DEFAULT 'srf' COMMENT 'srf = Superliga Frontier. ie = Inazuma Eleven Canonical Series. Solo decorativo.',
  `id_rareza` int(11) NOT NULL,
  `id_afinidad` int(11) NOT NULL,
  `ataque` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `defensa` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `tecnica` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `cupo_numerado` int(11) unsigned DEFAULT NULL,
  `origen_importacion` tinyint(1) NOT NULL DEFAULT 0,
  `solo_cadena` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1 = exclusiva de cadenas: ni sobres ni progreso de álbum',
  `en_sobres` tinyint(1) NOT NULL DEFAULT 1 COMMENT '1 = entra en el sorteo de los sobres. 0 = solo por otras vías (botín, códigos).',
  PRIMARY KEY (`id_cromo`),
  KEY `idx_cromos_expansion` (`id_expansion`),
  KEY `idx_cromos_equipo` (`id_equipo`),
  KEY `idx_cromos_rareza` (`id_rareza`),
  KEY `idx_cromos_afinidad` (`id_afinidad`),
  KEY `idx_cromos_solo_cadena` (`solo_cadena`),
  CONSTRAINT `fk_cromo_afinidad` FOREIGN KEY (`id_afinidad`) REFERENCES `afinidad` (`id`),
  CONSTRAINT `fk_cromo_equipo` FOREIGN KEY (`id_equipo`) REFERENCES `equipos` (`id_equipo`),
  CONSTRAINT `fk_cromo_expansion` FOREIGN KEY (`id_expansion`) REFERENCES `expansiones` (`id_expansion`),
  CONSTRAINT `fk_cromo_rareza` FOREIGN KEY (`id_rareza`) REFERENCES `rarezas` (`id_rareza`)
) ENGINE=InnoDB AUTO_INCREMENT=529 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `cromos`
--

LOCK TABLES `cromos` WRITE;
/*!40000 ALTER TABLE `cromos` DISABLE KEYS */;
