--
-- Table structure for table `duelo_alineaciones`
--

DROP TABLE IF EXISTS `duelo_alineaciones`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `duelo_alineaciones` (
  `id_alineacion` int(11) NOT NULL AUTO_INCREMENT,
  `id_duelo` int(11) NOT NULL,
  `id_usuario` int(11) NOT NULL,
  `hueco` tinyint(3) unsigned NOT NULL,
  `id_cromo` int(11) NOT NULL,
  `ataque` tinyint(3) unsigned NOT NULL,
  `defensa` tinyint(3) unsigned NOT NULL,
  `tecnica` tinyint(3) unsigned NOT NULL,
  `id_rareza` tinyint(3) DEFAULT NULL COMMENT 'Rareza con la que salió esta carta en ESTE duelo. NULL = la del catálogo.',
  PRIMARY KEY (`id_alineacion`),
  UNIQUE KEY `uq_alineacion_duelo_usuario_hueco` (`id_duelo`,`id_usuario`,`hueco`),
  KEY `idx_alineacion_cromo` (`id_cromo`),
  KEY `fk_alineacion_usuario` (`id_usuario`),
  CONSTRAINT `fk_alineacion_cromo` FOREIGN KEY (`id_cromo`) REFERENCES `cromos` (`id_cromo`),
  CONSTRAINT `fk_alineacion_duelo` FOREIGN KEY (`id_duelo`) REFERENCES `duelos` (`id_duelo`) ON DELETE CASCADE,
  CONSTRAINT `fk_alineacion_usuario` FOREIGN KEY (`id_usuario`) REFERENCES `usuarios` (`id_usuario`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=42923 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

